import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.O93z6AWZ.js";const u=JSON.parse('{"title":"APPENDIX — FAIR, TRIPOD+AI AND PROBAST+AI: DATA STEWARDSHIP, REPORTING AND APPRAISAL OF MEDICAL MACHINE LEARNING MODELS","description":"","frontmatter":{},"headers":[],"relativePath":"en/phu_luc_fair_tripod_probast.md","filePath":"en/phu_luc_fair_tripod_probast.md"}'),r={name:"en/phu_luc_fair_tripod_probast.md"};function s(n,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="appendix-—-fair-tripod-ai-and-probast-ai-data-stewardship-reporting-and-appraisal-of-medical-machine-learning-models" tabindex="-1">APPENDIX — FAIR, TRIPOD+AI AND PROBAST+AI: DATA STEWARDSHIP, REPORTING AND APPRAISAL OF MEDICAL MACHINE LEARNING MODELS <a class="header-anchor" href="#appendix-—-fair-tripod-ai-and-probast-ai-data-stewardship-reporting-and-appraisal-of-medical-machine-learning-models" aria-label="Permalink to &quot;APPENDIX — FAIR, TRIPOD+AI AND PROBAST+AI: DATA STEWARDSHIP, REPORTING AND APPRAISAL OF MEDICAL MACHINE LEARNING MODELS&quot;">​</a></h1><blockquote><p><strong>Used in:</strong> Machine Learning in Healthcare, supporting Chapter 2 (medical data) and Chapter 4 (validation and model evaluation). <strong>Source:</strong> condensed from the internal review of the AI-CDSS project (heart failure, Alzheimer&#39;s disease). Original review v2.2, dated 15/10/2026, with sources verified. All cited works are in <code>references/library.bib</code>; metadata checked against Crossref on 17/10/2026. <strong>The case studies</strong> are written as <strong>self-study prompts</strong>: the appendix poses questions and points to readings, and students read the original papers to answer them. Any figure not given in this appendix must be taken from the original paper, not guessed.</p></blockquote><hr><h2 id="_1-three-kinds-of-evidence-that-do-not-imply-one-another" tabindex="-1">1. Three kinds of evidence that do not imply one another <a class="header-anchor" href="#_1-three-kinds-of-evidence-that-do-not-imply-one-another" aria-label="Permalink to &quot;1. Three kinds of evidence that do not imply one another&quot;">​</a></h2><p>When reading or writing a medical machine learning study, keep three questions apart:</p><table tabindex="0"><thead><tr><th>Question</th><th>Reference framework</th><th>Common wrong answer</th></tr></thead><tbody><tr><td>Is the data managed so that it can be found, accessed under control, integrated and reused?</td><td><strong>FAIR</strong> [@wilkinson2016fair; @jacobsen2020fair]</td><td>&quot;The data is publicly online, so it is FAIR&quot;</td></tr><tr><td>Is the study reported fully enough for others to understand and reproduce it?</td><td><strong>TRIPOD+AI</strong> [@collins2024tripodai]</td><td>&quot;The paper has an AUC table, so reporting is complete&quot;</td></tr><tr><td>Are the methods trustworthy: risk of bias, applicability?</td><td><strong>PROBAST+AI</strong> [@moons2025probastai]</td><td>&quot;Reporting is complete, so the methods are sound&quot;</td></tr></tbody></table><p>These three kinds of evidence are independent:</p><ul><li>FAIR data is not necessarily representative of the population the model will be used on.</li><li>Complete reporting does not mean the design is correct.</li><li>A high AUC does not prove the model benefits patients.</li></ul><hr><h2 id="_2-fair-principles-for-data-stewardship" tabindex="-1">2. FAIR: principles for data stewardship <a class="header-anchor" href="#_2-fair-principles-for-data-stewardship" aria-label="Permalink to &quot;2. FAIR: principles for data stewardship&quot;">​</a></h2><h3 id="_2-1-the-four-components" tabindex="-1">2.1. The four components <a class="header-anchor" href="#_2-1-the-four-components" aria-label="Permalink to &quot;2.1. The four components&quot;">​</a></h3><p>FAIR consists of 15 sub-principles, labelled F1 to R1.3 [@wilkinson2016fair]. For how to interpret them in practice, see @jacobsen2020fair.</p><table tabindex="0"><thead><tr><th>Component</th><th>Meaning</th><th>Practical evidence (suggestions, not FAIR wording)</th></tr></thead><tbody><tr><td><strong>F</strong>indable</td><td>Persistent identifier, rich metadata, indexed</td><td>Identifier and version for the dataset; a description page covering source, time period, inclusion/exclusion criteria, sample size</td></tr><tr><td><strong>A</strong>ccessible</td><td>Accessed through a standard protocol, with authentication and authorization</td><td>Data request procedure, contact point, data use agreement (DUA). Metadata stays accessible even when the data is restricted</td></tr><tr><td><strong>I</strong>nteroperable</td><td>Uses a shared language and vocabulary</td><td>Variable dictionary and units; HL7 FHIR exchange standard [@hl7_fhir]; LOINC laboratory codes [@loinc_standard]</td></tr><tr><td><strong>R</strong>eusable</td><td>Described well enough to be reused: provenance, conditions of use</td><td>Provenance (extraction queries, mappings, edit history); conditions of use; limitations</td></tr></tbody></table><h3 id="_2-2-three-misconceptions-to-avoid" tabindex="-1">2.2. Three misconceptions to avoid <a class="header-anchor" href="#_2-2-three-misconceptions-to-avoid" aria-label="Permalink to &quot;2.2. Three misconceptions to avoid&quot;">​</a></h3><ol><li><strong>FAIR is not the same as open data.</strong> Patient data can be FAIR while access remains controlled.</li><li><strong>FAIR does not replace legal and ethical requirements.</strong> In Vietnam, health data is sensitive personal data under the Law on Personal Data Protection [@luat_bvdlcn_2025] and Decree 356/2025/NĐ-CP [@nghi_dinh_356_2025]. Receiving a data file does not prove that ethics approval or a DUA is in place.</li><li><strong>&quot;FAIR&quot; is not &quot;fairness&quot;.</strong> FAIR is about data stewardship. Fairness is about whether an algorithm treats patient groups equitably. They are different concepts.</li></ol><h3 id="_2-3-documentation" tabindex="-1">2.3. Documentation <a class="header-anchor" href="#_2-3-documentation" aria-label="Permalink to &quot;2.3. Documentation&quot;">​</a></h3><p>Every dataset should have a <strong>datasheet</strong> [@gebru2021datasheets] describing: motivation for collection, composition, collection and preprocessing process, recommended uses, limitations. In the course project, the datasheet is a required part of the data dossier (section 7).</p><hr><h2 id="_3-tripod-ai-transparent-reporting-of-prediction-models" tabindex="-1">3. TRIPOD+AI: transparent reporting of prediction models <a class="header-anchor" href="#_3-tripod-ai-transparent-reporting-of-prediction-models" aria-label="Permalink to &quot;3. TRIPOD+AI: transparent reporting of prediction models&quot;">​</a></h2><h3 id="_3-1-scope" tabindex="-1">3.1. Scope <a class="header-anchor" href="#_3-1-scope" aria-label="Permalink to &quot;3.1. Scope&quot;">​</a></h3><p>TRIPOD+AI [@collins2024tripodai] is a reporting guideline for studies that <strong>develop or evaluate clinical prediction models</strong>, covering both regression and machine learning. It has 27 items plus a separate checklist for the abstract. The official checklist is available on the TRIPOD website; students download it themselves.</p><h3 id="_3-2-choose-the-guideline-by-research-question-not-by-output-type" tabindex="-1">3.2. Choose the guideline by research question, not by output type <a class="header-anchor" href="#_3-2-choose-the-guideline-by-research-question-not-by-output-type" aria-label="Permalink to &quot;3.2. Choose the guideline by research question, not by output type&quot;">​</a></h3><p>A model that outputs a probability does not automatically call for TRIPOD+AI. Choose by the study&#39;s <strong>question and design</strong>:</p><table tabindex="0"><thead><tr><th>Research question</th><th>Reporting guideline</th></tr></thead><tbody><tr><td>Developing or validating a diagnostic/prognostic prediction model</td><td>TRIPOD+AI [@collins2024tripodai]</td></tr><tr><td>Accuracy of an AI-based test against a reference standard</td><td>STARD-AI [@sounderajah2025stardai]</td></tr><tr><td>Early-stage clinical evaluation of an AI decision support system</td><td>DECIDE-AI [@vasey2022decideai]</td></tr></tbody></table><hr><h2 id="_4-probast-ai-appraising-risk-of-bias-and-applicability" tabindex="-1">4. PROBAST+AI: appraising risk of bias and applicability <a class="header-anchor" href="#_4-probast-ai-appraising-risk-of-bias-and-applicability" aria-label="Permalink to &quot;4. PROBAST+AI: appraising risk of bias and applicability&quot;">​</a></h2><p>PROBAST+AI [@moons2025probastai] assesses two <strong>separate</strong> parts:</p><ul><li><strong>Model development:</strong> the quality of the model-building process.</li><li><strong>Model evaluation:</strong> the risk of bias in the performance evaluation, and applicability to the target population.</li></ul><p>The original paper contains tables of signalling questions grouped into four domains: participants and data sources, predictors, outcome, analysis. Students should read these tables in the original paper before doing the exercises in section 8.</p><p><strong>Why appraise?</strong> A systematic review of 152 studies of supervised machine learning models found that <strong>87%</strong> of the assessments had a high risk of bias. Common flaws were sample sizes too small for the number of predictors, inappropriate handling of missing data, and incorrect assessment of overfitting [@andaurnavarro2021rob].</p><p><strong>Methodological errors students often make (mapped to PROBAST+AI):</strong></p><ol><li><strong>Data leakage:</strong> scaling, imputation or feature selection on the full dataset before the train/test split. All of these steps must be fitted <strong>on the training set only</strong>.</li><li><strong>Splitting by row instead of by patient:</strong> a patient with several visits ends up in both the training and the test set.</li><li><strong>Using future information:</strong> using as input a variable that only becomes available after the decision time point (T0).</li><li><strong>Incorporation bias:</strong> the label is built from one of the input variables. Example: labelling heart failure with an NT-proBNP threshold and then using NT-proBNP to predict that label. Performance is inflated as a result.</li><li><strong>Treating data completeness as label correctness:</strong> a record with every variable filled in can still be mislabelled. Label quality must be assessed separately.</li></ol><hr><h2 id="_5-performance-evaluation-more-than-auc" tabindex="-1">5. Performance evaluation: more than AUC <a class="header-anchor" href="#_5-performance-evaluation-more-than-auc" aria-label="Permalink to &quot;5. Performance evaluation: more than AUC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Measure</th><th>Notes</th></tr></thead><tbody><tr><td>Discrimination</td><td>AUC/C-statistic</td><td>Says nothing about whether predicted probabilities are at the right level</td></tr><tr><td>Calibration</td><td>Calibration curve; <strong>calibration-in-the-large</strong> (intercept with the slope fixed at 1); <strong>calibration slope</strong></td><td>Calibration is the &quot;Achilles heel&quot; of predictive analytics [@vancalster2019calibration]. A slope &lt; 1 often signals overfitting</td></tr><tr><td>Overall performance</td><td>Brier score</td><td>Brier reflects discrimination, calibration and outcome prevalence together. <strong>Do not</strong> use Brier alone to conclude a model is well calibrated</td></tr><tr><td>Clinical utility</td><td>Decision curve analysis (net benefit)</td><td>Shows whether using the model at a given threshold beats the &quot;treat all&quot; or &quot;treat none&quot; strategies</td></tr></tbody></table><p><strong>Sample size is several different problems,</strong> with no single number:</p><ul><li>Model development: based on the number of parameters, outcome prevalence and acceptable overfitting [@riley2020samplesize].</li><li>External validation: based on the desired precision of the performance measures [@riley2024external].</li><li>Accuracy at a threshold, and intervention studies: need their own calculations.</li></ul><hr><h2 id="_6-case-studies-prompts-for-self-study" tabindex="-1">6. Case studies: prompts for self-study <a class="header-anchor" href="#_6-case-studies-prompts-for-self-study" aria-label="Permalink to &quot;6. Case studies: prompts for self-study&quot;">​</a></h2><p>Each case study has a <strong>short story</strong>, <strong>required reading</strong> and <strong>questions</strong>. Students answer with evidence quoted from the original paper: give the page, table or figure.</p><h3 id="_6-1-heart-failure" tabindex="-1">6.1. Heart failure <a class="header-anchor" href="#_6-1-heart-failure" aria-label="Permalink to &quot;6.1. Heart failure&quot;">​</a></h3><p><strong>Case HF-1. The heart failure survival dataset (UCI) and &quot;two variables are enough&quot;</strong></p><ul><li><strong>Read:</strong> @chicco2020machine. The paper concludes that serum creatinine and ejection fraction (EF) can predict survival.</li><li><strong>Questions:</strong><ol><li>How many patients does the dataset contain, and where and when was it collected? Is that population similar to heart failure patients aged ≥ 60 in Vietnam? (applicability, PROBAST+AI)</li><li>Should the <code>time</code> variable (follow-up time) be used as an input? Why might this leak future information?</li><li>Write a datasheet [@gebru2021datasheets] for this dataset. Which sections have <strong>no</strong> information?</li><li>Train a logistic regression and a tree-based model yourself. Report AUC, the calibration curve and Brier. Does the conclusion that &quot;two variables are enough&quot; still hold?</li></ol></li></ul><p><strong>Case HF-2. AI-ECG: from high AUC to real-world impact</strong></p><ul><li><strong>Read:</strong> @attia2019aiecg (development and validation of an AI reading the electrocardiogram to detect left ventricular dysfunction) and @yao2021eagle (the EAGLE pragmatic trial).</li><li><strong>Hint:</strong> AUC measures discrimination. EAGLE measures the change in diagnosis rate when clinicians have access to the tool, with an absolute increase of about 0.5 percentage points [@yao2021eagle]. The two measures answer different questions; <strong>do not compare their magnitudes directly</strong>.</li><li><strong>Questions:</strong><ol><li>Is the EF threshold used to define the label the same in the two studies? Can the figures from the two papers be combined?</li><li>What type of design is EAGLE? Which reporting guideline fits it (section 3.2)?</li><li>Why can a model with a high AUC still have a small clinical impact?</li></ol></li></ul><p><strong>Case HF-3. CoDE-HF: diagnosing acute heart failure based on NT-proBNP</strong></p><ul><li><strong>Read:</strong> @lee2022codehf (development and validation) and @doudesis2026codehf (prospective validation, <strong>a one-page conference abstract only</strong>).</li><li><strong>Questions:</strong><ol><li>Which variables does the model need <strong>at the time of prediction</strong>? If a hospital does not have NT-proBNP at the initial assessment, can the model be used?</li><li>How was the reference standard (the acute heart failure label) established? Is there a risk of incorporation bias?</li><li>Use TRIPOD+AI for Abstracts to assess the 2026 abstract. Which items have <strong>insufficient information</strong>? Why must details from the 2022 paper not be used to fill the gaps of the 2026 study?</li><li>Try appraising the 2026 abstract with the &quot;model evaluation&quot; part of PROBAST+AI. Can the conclusion be &quot;unclear&quot;, and why?</li></ol></li></ul><h3 id="_6-2-diabetes" tabindex="-1">6.2. Diabetes <a class="header-anchor" href="#_6-2-diabetes" aria-label="Permalink to &quot;6.2. Diabetes&quot;">​</a></h3><p><strong>Case DM-1. Diabetic retinopathy: from the laboratory to the clinic</strong></p><ul><li><strong>Read:</strong> in this order, @gulshan2016dr (development and validation of deep learning on fundus photographs), @abramoff2018autonomous (pivotal trial of an autonomous AI diagnostic system), @beede2020humancentered (human-centred evaluation of deployment in clinics).</li><li><strong>Questions:</strong><ol><li>Which question does each of the three papers answer? Which reporting guideline fits each one (STARD-AI, TRIPOD+AI, DECIDE-AI)?</li><li>According to @beede2020humancentered, which factors outside the model (image quality, workflow, infrastructure) make real-world effectiveness differ from laboratory results?</li><li>Who provided the reference standard (the image graders) in each study? How does that affect the interpretation of sensitivity and specificity?</li></ol></li></ul><p><strong>Case DM-2. Hospital readmission in diabetic patients: the 130 US hospitals dataset</strong></p><ul><li><strong>Read:</strong> @strack2014hba1c. The paper analyses about 70,000 records to see whether measuring HbA1c is associated with readmission. It is the origin of the &quot;Diabetes 130-US hospitals&quot; dataset commonly found on UCI.</li><li><strong>Questions:</strong><ol><li>Is each row a patient or a hospital admission? If you split train/test by row, is there leakage, and how should you split instead?</li><li>HbA1c is missing in most records. Is &quot;HbA1c not measured&quot; missing data or clinical information? Choose a handling approach and justify it with PROBAST+AI.</li><li>What mapping do the ICD-9 diagnosis codes in the dataset need to interoperate with Vietnamese data (ICD-10)? Which FAIR principle is this?</li></ol></li></ul><p><strong>Case DM-3. A community risk model for type 2 diabetes: QDiabetes-2018</strong></p><ul><li><strong>Read:</strong> @hippisleycox2017qdiabetes. Optionally read the review @kavakiotis2017diabetes for a broader picture of machine learning in diabetes research.</li><li><strong>Questions:</strong><ol><li>Which aspects from section 5 does the model report: discrimination, calibration, or both? What do you think is missing?</li><li>Using QDiabetes for Vietnamese people requires <strong>external validation</strong>. What inputs does the sample size calculation of @riley2024external need?</li><li>Compare the &quot;classical regression model on big data&quot; approach (QDiabetes) with the machine learning models in the review @kavakiotis2017diabetes. Which is easier to validate and explain?</li></ol></li></ul><p><strong>Further self-study (not in the reference library):</strong> the &quot;Pima Indians Diabetes&quot; dataset is often used in exercises. Find out for yourself where the dataset comes from, which population it was collected from, and issues such as zeros used in place of missing values. Then assess the dataset against sections 2 and 4 of this appendix.</p><hr><h2 id="_7-quick-checklist-for-the-course-project" tabindex="-1">7. Quick checklist for the course project <a class="header-anchor" href="#_7-quick-checklist-for-the-course-project" aria-label="Permalink to &quot;7. Quick checklist for the course project&quot;">​</a></h2><p><strong>Data (FAIR)</strong></p><ul><li>[ ] Datasheet: source, time period, population, inclusion/exclusion criteria, variable definitions and units, limitations.</li><li>[ ] Version and checksum of the data file used for training.</li><li>[ ] No patient identifiers. State the basis on which you may use the data (public data, licence, DUA).</li></ul><p><strong>Reporting (TRIPOD+AI)</strong></p><ul><li>[ ] The guideline was chosen by research question (section 3.2) and the completed checklist is attached.</li><li>[ ] Clear definitions of the outcome, the label, the prediction time point T0 and the variables available at T0.</li></ul><p><strong>Methods (PROBAST+AI)</strong></p><ul><li>[ ] Data split by patient. Every preprocessing step is fitted on the training set only.</li><li>[ ] A logistic regression baseline is included.</li><li>[ ] Report AUC, the calibration curve, calibration-in-the-large, slope and Brier, with 95% confidence intervals.</li><li>[ ] State whether the sample size is adequate, and the limits of applicability.</li></ul><hr><h2 id="_8-suggested-exercises" tabindex="-1">8. Suggested exercises <a class="header-anchor" href="#_8-suggested-exercises" aria-label="Permalink to &quot;8. Suggested exercises&quot;">​</a></h2><ol><li><strong>Appraise a paper:</strong> choose a medical machine learning paper on heart failure or diabetes. Assess its reporting against TRIPOD+AI and its methods against PROBAST+AI. Present a table: item code, location of the evidence in the paper, judgement, reason.</li><li><strong>Fix a leaky notebook:</strong> the lecturer provides a notebook with leakage errors (scaling before the split, splitting by row). Students find the errors, fix them and compare the AUC before and after the fix.</li><li><strong>Datasheet and FAIR:</strong> write a datasheet for a public dataset (UCI heart failure or Diabetes 130-US). Identify which FAIR principles are not met and what needs to be added.</li></ol><hr><h2 id="_9-reference-solutions-review-results-from-a-real-project" tabindex="-1">9. Reference solutions: review results from a real project <a class="header-anchor" href="#_9-reference-solutions-review-results-from-a-real-project" aria-label="Permalink to &quot;9. Reference solutions: review results from a real project&quot;">​</a></h2><blockquote><p>For lecturers, or for students to compare <strong>after</strong> they have done case HF-3 and exercise 1 on their own. The content is taken from the internal review of a hospital AI-CDSS heart failure project (v2.2, 15/10/2026). It follows the same format students are expected to submit: every judgement has an item code, the location of the evidence and a reason.</p></blockquote><h3 id="_9-1-code-hf-2026-appraising-a-conference-abstract" tabindex="-1">9.1. CoDE-HF 2026: appraising a conference abstract <a class="header-anchor" href="#_9-1-code-hf-2026-appraising-a-conference-abstract" aria-label="Permalink to &quot;9.1. CoDE-HF 2026: appraising a conference abstract&quot;">​</a></h3><p><strong>Step 1. Identify the type of evidence.</strong> @doudesis2026codehf is a <strong>one-page conference abstract</strong>, not a full paper. Therefore:</p><ul><li>reporting is assessed with <strong>TRIPOD+AI for Abstracts</strong> (13 items);</li><li>PROBAST+AI uses only the <strong>model evaluation part</strong> (18 questions) for a preliminary conclusion;</li><li>the 2022 development paper [@lee2022codehf] is background only and is <strong>not used to fill gaps</strong> in the 2026 study.</li></ul><p><strong>Step 2. Read the figures correctly.</strong> The abstract reports a cohort of 1,030 people, including 374 adjudicated cases of acute heart failure (AHF). Read carefully: the AUC of 0.839 (95% CI 0.809–0.869) and the Brier score of 0.152 <strong>apply only to the subgroup without a history of heart failure</strong>, not to the whole cohort. In that subgroup, CoDE-HF places 30% of cases in the low-risk group and 19% in the high-risk group, so about 51% remain in an <strong>intermediate zone</strong> that needs its own care pathway. Brier is an overall performance measure: 0.152 is <strong>not enough</strong> to conclude that calibration is good (section 5).</p><p><strong>Step 3. TRIPOD+AI for Abstracts.</strong></p><table tabindex="0"><thead><tr><th>Level</th><th>Items</th><th>Notes</th></tr></thead><tbody><tr><td>Reported</td><td>2 (background), 3 (objectives), 8 (performance measures), 9 (number of participants and outcomes, for the whole cohort), 10 (predictors, all 10 listed)</td><td>Item 8 only asks which measures were used; the missing calibration is handled under PROBAST+AI</td></tr><tr><td>Partly reported</td><td>1 (title does not state the population), 4 (data source does not state centres or time period), 5 (consecutive recruitment and exclusion criteria not stated), 6 (diagnostic criteria for AHF not stated), 11 (Brier without a CI)</td><td></td></tr><tr><td>Needs qualification</td><td>12 (concludes &quot;decision support&quot; although no impact study exists yet)</td><td></td></tr><tr><td>Not applicable</td><td>7 (model development methods, since this is an evaluation study)</td><td></td></tr><tr><td>Not found</td><td>13 (registration number)</td><td>Do not infer that the study was not registered</td></tr></tbody></table><p>This table is <strong>not</strong> converted into a &quot;compliance rate&quot;: the number of applicable items varies with the design, and there is no predefined rule for scoring &quot;Partly reported&quot;.</p><p><strong>Step 4. PROBAST+AI, model evaluation part.</strong> Answer codes: Y, PY, PN, N, NI (no information), NA.</p><table tabindex="0"><thead><tr><th>Domain</th><th>Key judgements</th><th>Domain conclusion</th></tr></thead><tbody><tr><td>1. Participants, data sources</td><td>Prospective cohort, an appropriate external validation design (PY); unclear whether recruitment was consecutive and how many cases were excluded (NI)</td><td>Unclear</td></tr><tr><td>2. Predictors</td><td>Assay, units, eGFR calculation and time of availability of predictors not stated (NI)</td><td>Unclear</td></tr><tr><td>3. Outcome</td><td>Adjudication panel (a strength), but &quot;two independent clinicians&quot; does not show blinding to NT-proBNP (NI)</td><td>Unclear</td></tr><tr><td>4. Analysis</td><td>Discrimination and accuracy at thresholds are reported; no calibration curve, no net benefit, no sample size justification (NI). The question on the train/test split is conditionally NA, since this is external validation</td><td>Unclear</td></tr></tbody></table><p><strong>Conclusion:</strong> the overall risk of bias is <strong>unclear due to missing information</strong>, neither &quot;high&quot; nor &quot;low&quot;. This is the right conclusion for an abstract: when information is missing, record it as missing; do not guess.</p><p><strong>Step 5. FAIR of the study.</strong> The paper has a DOI, so the <strong>paper</strong> is findable. The abstract gives no dataset identifier, data dictionary, data access conditions, or model code/version. There is therefore not enough evidence to conclude that the dataset is FAIR. Absence of evidence does not mean those records do not exist.</p><p><strong>Step 6. Documents needed to complete the appraisal:</strong></p><ul><li>protocol or SAP, registration number;</li><li>screening and exclusion flow diagram;</li><li>model version and locked thresholds;</li><li>AHF diagnostic criteria and blinding procedure;</li><li>proportion of missing data; assays and units;</li><li>confusion matrix at each threshold; calibration with CIs;</li><li>ethics approval and data access conditions.</li></ul><h3 id="_9-2-a-fair-audit-of-a-hospital-data-export-and-can-code-hf-be-validated" tabindex="-1">9.2. A FAIR audit of a hospital data export, and can CoDE-HF be validated? <a class="header-anchor" href="#_9-2-a-fair-audit-of-a-hospital-data-export-and-can-code-hf-be-validated" aria-label="Permalink to &quot;9.2. A FAIR audit of a hospital data export, and can CoDE-HF be validated?&quot;">​</a></h3><p><strong>Data:</strong> a wide-format laboratory export from a hospital, pseudonymised, not public: 330 rows, 13 columns. It contains a pseudonymous patient ID, sex, year of birth and 10 laboratory columns. It has no diagnoses, sampling times or units.</p><p><strong>FAIR, judged on the evidence contained in the data package:</strong></p><table tabindex="0"><thead><tr><th>Principle</th><th>Present</th><th>Needs to be added</th></tr></thead><tbody><tr><td>F (findable)</td><td>Only a file name</td><td>Dataset identifier and version, datasheet [@gebru2021datasheets], metadata with checksum</td></tr><tr><td>A (accessible)</td><td>The file was received, but no mechanism is described</td><td>Access procedure, authorization, DUA</td></tr><tr><td>I (interoperable)</td><td>Machine-readable CSV, but only local column names</td><td>Units; LOINC codes [@loinc_standard]; keys linking patient – visit – sample – time</td></tr><tr><td>R (reusable)</td><td>No variable definitions or provenance</td><td>Provenance (extraction queries, mappings, edit history), conditions of use</td></tr></tbody></table><p><strong>Conclusion:</strong> machine-readable, but <strong>not enough evidence</strong> of findability, controlled access and reusability. Do not label it &quot;FAIR / not FAIR&quot; using a self-defined total score.</p><p><strong>Gap analysis for validating CoDE-HF.</strong> CoDE-HF needs 10 predictors, plus the heart failure history variable to choose the branch and the reference AHF label:</p><table tabindex="0"><thead><tr><th>Readiness</th><th>Variables</th></tr></thead><tbody><tr><td>Directly available (1/10)</td><td>NT-proBNP. Units, assay and timing are still needed, and values equal to the analyser&#39;s upper limit must be checked</td></tr><tr><td>Derivable under conditions (2/10)</td><td>Age at assessment (needs the sampling date); eGFR (needs a valid creatinine, its unit and an approved formula)</td></tr><tr><td>Missing (7/10)</td><td>Haemoglobin, BMI, heart rate, systolic blood pressure, peripheral oedema, COPD, ischaemic heart disease</td></tr><tr><td>Missing, blocks evaluation</td><td>Heart failure history (the branch cannot be chosen); reference AHF label</td></tr></tbody></table><p><strong>Inferences to avoid:</strong></p><ul><li>Do not use <code>NT_proBNP ≥ 300</code> as the label and then report the AUC of a model that includes NT-proBNP. That is circular and cannot evaluate an independent diagnosis (incorporation bias, section 4).</li><li>Do not treat a missing medical history as &quot;no disease&quot;, and do not treat cases with a missing label as negative.</li><li>Do not conclude whether the sample size is adequate from an export that has no labels.</li><li>Do not divide suspected wrong-unit values by 10 or 100 on your own. Trace them back to the laboratory source.</li></ul><h3 id="_9-3-design-lessons-from-the-project-review" tabindex="-1">9.3. Design lessons from the project review <a class="header-anchor" href="#_9-3-design-lessons-from-the-project-review" aria-label="Permalink to &quot;9.3. Design lessons from the project review&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem found in the review</th><th>Correct approach</th></tr></thead><tbody><tr><td>The proposal stated &quot;records with complete variables (Tier A) are the ground truth&quot;</td><td>Separate three independent axes: completeness of inputs; quality of the label/reference standard; availability of variables at T0</td></tr><tr><td>TRIPOD+AI was chosen &quot;because the output is a probability&quot;</td><td>Choose by research question: TRIPOD+AI / STARD-AI / DECIDE-AI (section 3.2)</td></tr><tr><td>One sample size target for every stage</td><td>Calculate separately for development [@riley2020samplesize], external validation [@riley2024external], accuracy at a threshold, and intervention</td></tr><tr><td>&quot;Good Brier, so good calibration&quot;</td><td>Brier is overall performance. Report the curve, calibration-in-the-large and slope [@vancalster2019calibration]</td></tr><tr><td>Comparing the size of an AUC with the increase in diagnosis rate in a trial</td><td>The two measures answer different questions [@yao2021eagle]</td></tr><tr><td>The test set contains only complete-data cases</td><td>The evaluation set must reflect the real case flow at T0. If the system refuses to predict when variables are missing, report the refusal rate</td></tr><tr><td>Drug safety rules are &quot;outside the scope of the guideline&quot;</td><td>PROBAST+AI is not used to score rules, but an intervention report must still describe the rule source, version, known errors and clinician override behaviour</td></tr></tbody></table><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>All citation keys above are in <code>references/library.bib</code>, including 21 entries added on 17/10/2026 with metadata checked against Crossref by DOI.</p>',96)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
